// USDA FSIS FoodKeeper lookup (server-side). Data comes from data/foodkeeper-lite.json,
// generated by scripts/build-foodkeeper.mjs. Shelf-life values are in days, null when not given.
import "server-only";
import products from "@/data/foodkeeper-lite.json";

export const STORAGES = ["pantry", "refrigerator", "freezer"] as const;
export type Storage = (typeof STORAGES)[number];

type FoodKeeperProduct = {
  id: number;
  name: string;
  keywords: string | null;
  pantry: number | null;
  refrigerator: number | null;
  freezer: number | null;
  tips?: Partial<Record<Storage, string>>;
};

const PRODUCTS = products as FoodKeeperProduct[];
const BY_ID = new Map(PRODUCTS.map((p) => [p.id, p]));

// Compact "id|name" list for the prompt
export const FOODKEEPER_LIST = PRODUCTS.map((p) => `${p.id}|${p.name}`).join("\n");

export function findFoodKeeper(id: unknown): FoodKeeperProduct | null {
  const n = typeof id === "string" ? Number(id) : id;
  return typeof n === "number" && Number.isInteger(n) ? BY_ID.get(n) ?? null : null;
}
